static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    // Validate timeBucket format (YYYYMMDD)
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Basic range checks
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    int daysInMonth = daysInMonth(year, month);
    if (day < 1 || day > daysInMonth) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    // Compute bucket start day
    int bucketDay = ((day - 1) / dayStep) * dayStep + 1;

    // Construct new time bucket
    return year * 10000L + month * 100L + bucketDay;
}

private static int daysInMonth(int year, int month) {
    int[] days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int d = days[month - 1];
    if (month == 2 && isLeapYear(year)) {
        d = 29;
    }
    return d;
}

private static boolean isLeapYear(int year) {
    if (year % 4 != 0) {
        return false;
    }
    if (year % 100 != 0) {
        return true;
    }
    return year % 400 == 0;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input CharSequence is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 >= end) {
                throw new IllegalArgumentException("High surrogate at end of range without low surrogate");
            }
            char low = str.charAt(i + 1);
            if (!Character.isLowSurrogate(low)) {
                throw new IllegalArgumentException("High surrogate not followed by low surrogate");
            }
            // Code point > 0xFFFF => 4 bytes
            size += 4;
            i++; // skip low surrogate
        } else if (Character.isLowSurrogate(ch)) {
            throw new IllegalArgumentException("Unpaired low surrogate encountered");
        } else {
            size += 3;
        }
    }
    return size;
}

