public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    try {
        double minX = box.getMinX();
        double maxX = box.getMaxX();
        double minY = box.getMinY();
        double maxY = box.getMaxY();
        if (minX > maxX || minY > maxY) {
            throw new IllegalArgumentException("Box coordinates are invalid");
        }
        double midX = (minX + maxX) / 2.0;
        Box2D left = new Box2D(minX, minY, midX, maxY);
        Box2D right = new Box2D(midX, minY, maxX, maxY);
        return new Pair<>(left, right);
    } catch (Exception e) {
        throw new RuntimeException("Error splitting box along X axis", e);
    }
}

private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("Size must be positive");
    }
    // Determine new capacity, guarding against integer overflow
    int newCapacity;
    try {
        newCapacity = Math.addExact(this.capacity, size);
    } catch (ArithmeticException e) {
        newCapacity = Integer.MAX_VALUE;
    }
    if (newCapacity < 0) {
        newCapacity = Integer.MAX_VALUE;
    }
    // Allocate new array and copy existing data
    byte[] newBytes = new byte[newCapacity];
    System.arraycopy(this.bytes, 0, newBytes, 0, this.length);
    // Replace old array and update capacity
    this.bytes = newBytes;
    this.capacity = newCapacity;
}

