public static String capitalize(String name) {
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    // If the first two characters are both uppercase, return unchanged
    if (len > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise, capitalize the first character
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (first == upperFirst) {
        return name;
    }
    return upperFirst + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new NullPointerException("DataOutput is null");
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Attempt to access typical fields of LinkedBuffer
        try {
            int start = current.start;
            int end = current.end;
            if (start < 0 || end < start) {
                throw new IOException("Invalid buffer indices in LinkedBuffer");
            }
            int len = end - start;
            if (len > 0) {
                out.write(current.buf, start, len);
                total += len;
            }
            current = current.next;
        } catch (NoSuchFieldError | NoSuchMethodError | IllegalAccessError e) {
            // Fallback: try to use reflection if fields are not directly accessible
            try {
                java.lang.reflect.Field bufField = current.getClass().getDeclaredField("buf");
                java.lang.reflect.Field startField = current.getClass().getDeclaredField("start");
                java.lang.reflect.Field endField = current.getClass().getDeclaredField("end");
                java.lang.reflect.Field nextField = current.getClass().getDeclaredField("next");
                bufField.setAccessible(true);
                startField.setAccessible(true);
                endField.setAccessible(true);
                nextField.setAccessible(true);
                byte[] buf = (byte[]) bufField.get(current);
                int start = startField.getInt(current);
                int end = endField.getInt(current);
                int len = end - start;
                if (len > 0) {
                    out.write(buf, start, len);
                    total += len;
                }
                current = (LinkedBuffer) nextField.get(current);
            } catch (Exception ex) {
                throw new IOException("Failed to access LinkedBuffer internals", ex);
            }
        }
    }
    return total;
}

