public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }
    // Reset read pointer
    this.pos = 0;
    // Ensure buffer is initialized
    if (this.buffer == null || this.buffer.length == 0) {
        this.buffer = new byte[8192];
    }
    int totalRead = 0;
    int read;
    while ((read = in.read(this.buffer, totalRead, this.buffer.length - totalRead)) != -1) {
        totalRead += read;
        if (totalRead == this.buffer.length) {
            // Grow buffer
            int newCap = this.buffer.length * 2;
            byte[] newBuf = new byte[newCap];
            System.arraycopy(this.buffer, 0, newBuf, 0, this.buffer.length);
            this.buffer = newBuf;
        }
    }
    this.limit = totalRead;
    this.capacity = this.buffer.length;
}

