@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Validate target type
    if (type == null) {
        throw new Exception("Target type cannot be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new Exception("Unsupported target type: " + type.getName());
    }

    // Handle null value
    if (value == null) {
        if (char.class.equals(type)) {
            throw new Exception("Cannot convert null to primitive char");
        }
        return null;
    }

    // If already a Character, return as is
    if (value instanceof Character) {
        return value;
    }

    // Convert from String
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert String of length " + str.length() + " to Character");
        }
    }

    // Convert from Number
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }

    // Convert from char array of length 1
    if (value instanceof char[]) {
        char[] arr = (char[]) value;
        if (arr.length == 1) {
            return arr[0];
        } else {
            throw new Exception("Cannot convert char array of length " + arr.length + " to Character");
        }
    }

    // Unsupported conversion
    throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
}

