public static int nextPrime(int desiredCapacity){
    try {
        if (desiredCapacity <= 2) {
            return 2;
        }
        long candidate = desiredCapacity;
        if (candidate % 2 == 0) {
            candidate++;
        }
        long limit;
        if (desiredCapacity >= 1000) {
            limit = (long) desiredCapacity * 111L / 100L; // within 11%
        } else {
            limit = Integer.MAX_VALUE;
        }
        while (candidate <= limit) {
            if (isPrime((int) candidate)) {
                return (int) candidate;
            }
            candidate += 2;
        }
        // If not found within the 11% range, continue searching beyond it
        while (candidate <= Integer.MAX_VALUE) {
            if (isPrime((int) candidate)) {
                return (int) candidate;
            }
            candidate += 2;
        }
        throw new IllegalArgumentException("No prime found within int range");
    } catch (Exception e) {
        throw new IllegalArgumentException("Error computing next prime", e);
    }
}

private static boolean isPrime(int n){
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

