    try {
        // If no buffers have been written, return an empty array
        if (buffers == null || buffers.isEmpty()) {
            return new byte[0];
        }

        // Compute the total size needed for the combined array
        int totalSize = 0;
        for (byte[] buf : buffers) {
            if (buf != null) {
                totalSize += buf.length;
            }
        }

        // Allocate the result array
        byte[] result = new byte[totalSize];
        int offset = 0;

        // Copy each buffer into the result array
        for (byte[] buf : buffers) {
            if (buf != null && buf.length > 0) {
                System.arraycopy(buf, 0, result, offset, buf.length);
                offset += buf.length;
            }
        }

        return result;
    } catch (OutOfMemoryError e) {
