public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("Negative input not allowed");
    }
    if (n > 20) { // 20! is the largest factorial that fits in a long
        throw new ArithmeticException("Factorial result overflows a long");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("Factorial result overflows a long");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Validate arguments
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("Direction must be 1 (clockwise) or -1 (counter‑clockwise)");
    }

    try {
        // Create a circulator starting at the given node and direction
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
        Node current = circ.getNode();

        // If the start node is already the stop node, return immediately
        if (current.equals(stop)) {
            return circ;
        }

        // Traverse the outer face until we reach the stop node or loop back to start
        while (!current.equals(stop)) {
            // If the current node satisfies the predicate, return this circulator
            if (predicate.test(current)) {
                return circ;
            }

            // Move to the next node in the specified direction
            if (dir == 1) {
                circ.next();
            } else {
                circ.prev();
            }

            current = circ.getNode();

            // Prevent infinite loops: if we return to the start node, stop searching
            if (current.equals(start)) {
                break;
            }
        }

        // If we exited the loop without finding the predicate, return the circulator at the stop node
        // (if we reached it) or the current position (which is the start node if stop was not found).
        return circ;
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception with context
        throw new RuntimeException("Failed to select node on outer face", e);
    }
}

