public byte readByte() throws IOException {
    // Validate that the buffer and input stream are available
    if (buffer == null) {
        throw new IOException("Buffer is not initialized");
    }
    if (buffer.length == 0) {
        throw new IOException("Buffer size is zero");
    }
    if (in == null) {
        throw new IOException("Input stream is not initialized");
    }

    // Refill the buffer if all bytes have been consumed
    while (bufferPos >= bufferLimit) {
        bufferLimit = in.read(buffer);
        if (bufferLimit == -1) {
            throw new IOException("End of stream");
        }
        // If the read returned 0 bytes, try again (this can happen on non-blocking streams)
        if (bufferLimit == 0) {
            continue;
        }
        bufferPos = 0;
    }

    // Return the next byte and advance the position
    return buffer[bufferPos++];
}

