private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    try {
        // Basic check: if node is not the head or tail and has no links, it's not part of this list
        if (node != head && node != tail && node.prev == null && node.next == null) {
            return false;
        }

        // Remove node from the list
        if (node.prev == null) { // node is head
            head = node.next;
            if (head != null) {
                head.prev = null;
            } else {
                tail = null; // list became empty
            }
        } else {
            node.prev.next = node.next;
        }

        if (node.next == null) { // node is tail
            tail = node.prev;
            if (tail != null) {
                tail.next = null;
            } else {
                head = null; // list became empty
            }
        } else {
            node.next.prev = node.prev;
        }

        // Help garbage collection
        node.next = null;
        node.prev = null;
        size--;
        return true;
    }

