private String parseToken(final char[] terminators){
    // Ensure the input string is available
    if (input == null) {
        throw new IllegalStateException("Input string is null");
    }
    // If the current position is already at or beyond the end, return empty token
    if (pos >= input.length() || pos < 0) {
        return "";
    }
    // If no terminators are provided, consume the rest of the input
    if (terminators == null || terminators.length == 0) {
        String token = input.substring(pos);
        pos = input.length();
        return token;
    }
    StringBuilder sb = new StringBuilder();
    while (pos < input.length()) {
        char current = input.charAt(pos);
        boolean isTerminator = false;
        for (char t : terminators) {
            if (current == t) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break; // stop before the terminator
        }
        sb.append(current);
        pos++;
    }
    return sb.toString();
}

