private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null or empty input gracefully
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long suffixSum = 0L;
    long total = 0L;

    // Compute suffix sums from the end of the list
    for (int i = n - 1; i >= 0; i--) {
        int value = bounds.get(i);
        suffixSum += value;
        // Cast to int for the result list; overflow will wrap as per Java semantics
        suffix.add(0, (int) suffixSum);
        total += value;
    }

    return new Pair<>(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException("Indices out of bounds");
    }
    if (from > to) {
        throw new IllegalArgumentException("From index must be less than or equal to to index");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Validate input
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    if (list == this) {
        // Nothing to do if the same list
        return;
    }
    // If the source list is empty, nothing to move
    if (list.size == 0) {
        return;
    }

    // If this list is empty, simply adopt the source list's nodes
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Connect the two lists
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }

    // Update sizes
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If the prefix is null but the string is not, it's not a match
    if (prefix == null) {
        return false;
    }
    // If ignoreCase is true, use regionMatches with ignoreCase flag
    if (ignoreCase) {
        // regionMatches handles length checks internally
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    // Default case-sensitive comparison
    return str.startsWith(prefix);
}

