public void putAllWriteable(BeanMap map) {
    if (map == null) {
        throw new IllegalArgumentException("Source BeanMap cannot be null");
    }
    try {
        String[] names = map.getPropertyNames();
        if (names == null) {
            return;
        }
        for (String name : names) {
            if (name == null) {
                continue;
            }
            // Only copy properties that are readable and writable in the source
            // and writable in this BeanMap
            if (map.isReadable(name) && map.isWritable(name) && this.isWritable(name)) {
                Object value = map.getProperty(name);
                this.setProperty(name, value);
            }
        }
    } catch (IllegalAccessException | InvocationTargetException e) {
        throw new IllegalArgumentException("Failed to copy properties from source BeanMap", e);
    } catch (Exception e) {
        // Catch any other unexpected exceptions and wrap them
        throw new IllegalArgumentException("Unexpected error during putAllWriteable", e);
    }
}

