private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // A clique with 0 or 1 vertex is trivially true
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        if (v1 == null) {
            throw new IllegalArgumentException("Vertices set contains null");
        }
        for (V v2 : vertices) {
            if (v2 == null) {
                throw new IllegalArgumentException("Vertices set contains null");
            }
            if (!v1.equals(v2) && graph.getEdge(v1, v2) == null) {
                return false;
            }
        }
    }
    return true;
}

