public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    // Trim whitespace
    path = path.trim();
    relativePath = relativePath.trim();
    if (path.isEmpty() || relativePath.isEmpty()) {
        // If relativePath is empty, return the original path
        if (relativePath.isEmpty()) {
            return path;
        }
        throw new IllegalArgumentException("Path and relativePath must not be empty");
    }

    // Determine if the path is absolute
    boolean isAbsolute = path.startsWith("/");
    // Split the base path into components
    String[] baseParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    // If path ends with a slash, keep all parts; otherwise drop the last part (file)
    int limit = baseParts.length;
    if (!path.endsWith("/")) {
        limit = Math.max(0, baseParts.length - 1);
    }
    for (int i = 0; i < limit; i++) {
        if (!baseParts[i].isEmpty()) {
            stack.add(baseParts[i]);
        }
    }

    // Process the relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip empty or current directory references
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else if (!isAbsolute) {
                // For relative paths, we can keep leading ".." if stack is empty
                stack.add("..");
            }
            // If absolute and stack empty, ignore further ".."
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // If result is empty, return "." to represent current directory
    if (result.length() == 0) {
        return ".";
    }
    return result.toString();
}

