static String[] toNoNullStringArray(Object[] array){
    // Return null if the input array itself is null
    if (array == null) {
        return null;
    }

    // Count non-null elements
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }

    // If there are no nulls, we can return the original array if it is already a String[]
    if (nonNullCount == array.length) {
        if (array instanceof String[]) {
            return (String[]) array;
        }
        // Otherwise create a new array of the same length and copy elements
        String[] result = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            Object obj = array[i];
            if (obj != null) {
                if (!(obj instanceof String)) {
                    throw new IllegalArgumentException("Array contains non-String element at index " + i);
                }
                result[i] = (String) obj;
            }
        }
        return result;
    }

    // There are null elements; create a new array without them
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (int i = 0; i < array.length; i++) {
        Object obj = array[i];
        if (obj != null) {
            if (!(obj instanceof String)) {
                throw new IllegalArgumentException("Array contains non-String element at index " + i);
            }
            result[idx++] = (String) obj;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int sepIndex = indexOfLastSeparator(filename);
    if (sepIndex > dotIndex) {
        return -1;
    }
    return dotIndex;
}

private static int indexOfLastSeparator(String filename){
    if (filename == null) {
        return -1;
    }
    int lastSlash = filename.lastIndexOf('/');
    int lastBackslash = filename.lastIndexOf('\\');
    return Math.max(lastSlash, lastBackslash);
}

public boolean isExpired(long timestamp, long expiredThreshold) {
