        long current = System.currentTimeMillis();
        if (timestamp > current) {
            return false;
        }
        return (current - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, assume not expired
        return false;
    }
}

Edge edgeToNext() {
    try {
        // Ensure that the required nodes are available
        if (previousNode == null || nextNode == null) {
            throw new IllegalStateException("Previous or next node is not set.");
        }

        Node from = previousNode;
        Node to = nextNode;

        // Resolve virtual nodes to their real counterparts
        if (from.isVirtual()) {
            from = getRealNode(from);
            if (from == null) {
                throw new IllegalArgumentException("Real counterpart for virtual node not found.");
            }
        }

        if (to.isVirtual()) {
            to = getRealNode(to);
            if (to == null) {
                throw new IllegalArgumentException("Real counterpart for virtual node not found.");
            }
        }

        // Create and return the edge
        return new Edge(from, to);
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception with context
        throw new RuntimeException("Failed to create edge to next node", e);
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Validate inputs
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();

    // Index must be within bounds to accommodate the substring
    if (index < 0 || index > strLen - subLen) {
        return false;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (message == null) {
        message = "";
    }
    byte[] bytes = message.getBytes();
    synchronized (clients) {
        Iterator<Socket> it = clients.iterator();
        while (it.hasNext()) {
            Socket socket = it.next();
            try {
                OutputStream out = socket.getOutputStream();
                out.write(bytes);
                out.flush();
            } catch (IOException e) {
                it.remove();
                System.err.println("Failed to write to client socket: " + socket + " - " + e.getMessage());
            }
        }
    }
}

public static String toString(final char ch) {
    if (ch < 128) {
        return CHAR_CACHE[ch];
    }
    return String.valueOf(ch);
}

private void checkIfPackedField() throws IOException {
    // If the current field is encoded as length-delimited (wire type 2),
    // it might be a packed repeated field.  Check if the field number
    // is one that is known to be packed.  If so, read the length
    // and set the internal flag so that subsequent reads treat the
    // data as a packed block.
    if (currentWireType == 2) {
        // length-delimited
        if (packedFieldNumbers != null && packedFieldNumbers.contains(currentFieldNumber)) {
            // read the length of the packed data
            packedFieldLength = input.readRawVarint32();
            // mark that we are now reading a packed field
            isReadingPackedField = true;
        }
    }
}

public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = input.read();
        if (b == -1) {
            return 0; // EOF
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed varint");
        }
    }
}

final ByteVector put11(final int byteValue1, final int byteValue2){
    // Validate input values to be within byte range
    if (byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255) {
        throw new IllegalArgumentException("byte values must be in the range 0-255");
    }
    // Ensure the internal array exists and has enough capacity
    if (data == null) {
        data = new byte[16];
    } else if (size + 2 > data.length) {
        int newCapacity = Math.max(16, data.length * 2);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }
    // Append the two bytes
    data[size++] = (byte) byteValue1;
    data[size++] = (byte) byteValue2;
    return this;
}

private String buildContentRange() {
    try {
        java.lang.reflect.Field startField = this.getClass().getDeclaredField("start");
        java.lang.reflect.Field endField = this.getClass().getDeclaredField("end");
        java.lang.reflect.Field totalField = this.getClass().getDeclaredField("totalLength");
        startField.setAccessible(true);
        endField.setAccessible(true);
        totalField.setAccessible(true);
        Object startObj = startField.get(this);
        Object endObj = endField.get(this);
        Object totalObj = totalField.get(this);
        long start = startObj instanceof Number ? ((Number) startObj).longValue() : 0L;
        long end = endObj instanceof Number ? ((Number) endObj).longValue() : 0L;
        long total = totalObj instanceof Number ? ((Number) totalObj).longValue() : -1L;
        if (start < 0 || end < start) {
            return "";
        }
        if (total < 0) {
            return String.format("bytes %d-%d/*", start, end);
        } else {
            return String.format("bytes %d-%d/%d", start, end, total);
        }
    } catch (NoSuchFieldException | IllegalAccessException e) {
        return "";
    } catch (Exception e) {
        return "";
    }
}

public static java.util.List<ThreadSnapshot> parseFromFileWithTimeRange(java.io.File file, java.util.List<ProfileAnalyzeTimeRange> timeRanges) throws java.io.IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    boolean filterByRange = timeRanges != null && !timeRanges.isEmpty();
    try (java.util.Scanner scanner = new java.util.Scanner(file)) {
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            // Assume the line starts with a timestamp in milliseconds followed by a space.
            int firstSpace = line.indexOf(' ');
            if (firstSpace <= 0) {
                continue;
            }
            String tsStr = line.substring(0, firstSpace);
            long ts;
            try {
                ts = Long.parseLong(tsStr);
            } catch (NumberFormatException e) {
                continue;
            }
            if (filterByRange) {
                boolean inRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    long start = range.getStartTime();
                    long end = range.getEndTime();
                    if (ts >= start && ts <= end) {
                        inRange = true;
                        break;
                    }
                }
                if (!inRange) {
                    continue;
                }
            }
            ThreadSnapshot snapshot = null;
            // Try to parse the snapshot using a static parse method if available.
            try {
                java.lang.reflect.Method parseMethod = ThreadSnapshot.class.getMethod("parse", String.class);
                snapshot = (ThreadSnapshot) parseMethod.invoke(null, line);
            } catch (Exception e) {
                // Fallback: try a constructor that accepts a String.
                try {
                    java.lang.reflect.Constructor<?> ctor = ThreadSnapshot.class.getConstructor(String.class);
                    snapshot = (ThreadSnapshot) ctor.newInstance(line);
                } catch (Exception ex) {
                    // If neither method is available, skip this line.
                }
            }
            if (snapshot != null) {
                result.add(snapshot);
            }
        }
    }
    return result;
}
